#!/bin/bash
# Replay of the K(3,5) >= 47 LP/Farkas certificate chain from the vendored kakeya-fq sources.
# Verification only: no LP solver is run; every saved integer multiplier vector is re-applied
# exactly (Fractions) to rows regenerated by the vendored model code.  This is the ORIGINAL
# research code (lp/src, snapshot with sha256 in MANIFEST.sha256), not a fresh re-implementation:
# the trust base is lp/src/planecount5.py (the Farkas check), the row generators
# (planecount6.py and the session-XIV families) and the hand lemmas listed in README.md.
# usage: bash replay_lp.sh [hand|reduction|5|6|7|manifest|all]   (default: hand)
set -euo pipefail
cd "$(dirname "$0")"
ROOT=$(cd .. && pwd)
PY=${PY:-$ROOT/.venv/bin/python}     # needs numpy, scipy, sympy; see README "LP chain"
export OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1 MKL_NUM_THREADS=1
export PC6_SECTIONS=1 PC6_EXACT_K=4 PC6_F6_RMIN=5 PC6_DMH=1 PC6_UNMARKED=1
unset PC6_MFIX PLANE10_FULL
mkdir -p out log
[ -e src/out ] || ln -s ../out src/out
# the vendored scripts read and write 'out/...' relative to src/ (src/out -> ../out): seed it with
# copies of the certificate inputs (never symlinks: the replay rewrites some records)
for f in certs/*; do [ -f "$f" ] && { [ -e "out/$(basename "$f")" ] || cp "$f" out/; }; done
[ -e out/cert14_lower46.log ] || cp certs/cert14_lower46.log.txt out/cert14_lower46.log   # stored as .txt: *.log is git-ignored
mkdir -p src/solutions; for f in certs/solutions/*.json; do [ -e "src/solutions/$(basename "$f")" ] || cp "$f" src/solutions/; done                        # the four witness sets final14.py re-checks
# large inputs (price tables / type lists, 600 MB) are not in git: big/lp_inputs/, pinned by lp/BIG_INPUTS.sha256
(cd ../big/lp_inputs 2>/dev/null && sha256sum -c --quiet "$ROOT/lp/BIG_INPUTS.sha256") || { echo "big/lp_inputs missing or hash mismatch (see BIG_INPUTS.sha256; README 'LP chain')" >&2; exit 1; }
for f in ../big/lp_inputs/*.json; do [ -e "out/$(basename "$f")" ] || cp "$f" out/; done
[ -e src/.venv/bin/python ] || ln -sfn "$(dirname "$PY")/.." src/.venv
cd src
run() { echo "== $*"; /usr/bin/time -f "wall %e s maxrss %M KB" nice -n 19 "$PY" ../trace_open.py ../log/opened_files.tsv "$@"; }
case "${1:-hand}" in
  hand)      (cd .. && python3 ../src/k35_lower46_check.py) ;;
  reduction) run reduction14.py ;;                      # the 82 inherited reduction certificates (r_max, configurations, D range)
  5)         run replay14_D5.py --fresh-prices ;;
  6|7)       run coverage14.py --D "$1" --replay --fresh-prices ;;
  manifest)  run final14.py ;;
  all)       run reduction14.py; run replay14_D5.py --fresh-prices; run coverage14.py --D 6 --replay --fresh-prices; run coverage14.py --D 7 --replay --fresh-prices; run final14.py ;;
  *) echo "usage: replay_lp.sh [hand|reduction|5|6|7|manifest|all]" >&2; exit 2 ;;
esac
